type LifecycleStage = 'onboarding' | 'active' | 'at-risk' | 'collections';
type EvidenceFreshness = 'current' | 'stale' | 'unavailable' | 'restricted';
type ItemActionStatus = 'succeeded' | 'failed' | 'conflict' | 'permission-denied';

interface EvidenceRef {
  evidenceId: string;
  customerId: string;
  kind: 'last-activity' | 'open-invoice';
  label: string;
  value: string;
  observedAt: string;
  version: number;
  freshness: EvidenceFreshness;
}

interface ProposedLifecycleEdit {
  customerId: string;
  currentStage: LifecycleStage;
  suggestedStage: LifecycleStage;
  explanation: string;
  evidenceIds: string[];
}

interface GeneratedProposalContent {
  proposalId: string;
  proposalVersion: number;
  summary: string;
  edits: ProposedLifecycleEdit[];
  uncertainty: string[];
}

interface ActionEligibility {
  customerId: string;
  canApprove: boolean;
  reasons: string[];
  permissionVersion: number;
  customerVersion: number;
  evidenceVersions: Record<string, number>;
}

interface ProposalEnvelope {
  content: GeneratedProposalContent;
  evidenceById: Record<string, EvidenceRef>;
  eligibilityByCustomerId: Record<string, ActionEligibility>;
  checkedAt: string;
}

interface ReviewState {
  proposalId: string;
  proposalVersion: number;
  selectedCustomerIds: string[];
  stageOverrides: Record<string, LifecycleStage>;
  reviewedEvidenceVersions: Record<string, number>;
  reviewRevision: number;
}

interface ApprovedLifecycleEdit {
  customerId: string;
  fromStage: LifecycleStage;
  toStage: LifecycleStage;
  expectedCustomerVersion: number;
  expectedPermissionVersion: number;
  expectedEvidenceVersions: Record<string, number>;
}

interface ApprovalCommand {
  commandId: string;
  proposalId: string;
  proposalVersion: number;
  reviewRevision: number;
  edits: ApprovedLifecycleEdit[];
}

interface ItemActionOutcome {
  customerId: string;
  status: ItemActionStatus;
  resultingStage?: LifecycleStage;
  message: string;
  auditEventId: string;
  rollbackToken?: string;
}

interface ActionOutcome {
  commandId: string;
  status: 'completed' | 'mixed' | 'failed';
  items: ItemActionOutcome[];
  resolvedAt: string;
}
